namespace {
// Canonical new /Game/Folder/Name.Name destination with no loaded or on-disk package; returns package and object names.
void NewFoliageAssetPath(const FString& Path, FString& Package, FString& Object)
{
 if(Path.IsEmpty() || Path.Len()>2048 || !Path.Split(TEXT("."),&Package,&Object) || !Package.StartsWith(TEXT("/Game/")) || FPackageName::GetLongPackageAssetName(Package)!=Object) throw std::runtime_error("Canonical new /Game/Folder/Name.Name asset path required");
 for(TCHAR Ch:Object) if(!FChar::IsAlnum(Ch) && Ch!=TEXT('_')) throw std::runtime_error("Asset name requires letters/digits/underscore");
 if(LoadObject<UObject>(nullptr,*Path) || FPackageName::DoesPackageExist(Package)) throw std::runtime_error("Destination package already exists; no overwrite supported");
}
}

FString FoliageUtils::CreateType(const FFoliageReq& R)
{
 FoliageEditorWorld(); if(!GEditor->Trans || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor required");
 FString Package,Object; NewFoliageAssetPath(R.TypePath,Package,Object);
 UStaticMesh* Mesh=nullptr; if(!R.AssetPath.IsEmpty()) { Mesh=LoadObject<UStaticMesh>(nullptr,*R.AssetPath); if(!IsValid(Mesh) || !Mesh->IsAsset()) throw std::runtime_error("Loadable persistent static mesh required (empty for none)"); }
 if(!R.bDryRun)
 {
  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Create Foliage Type")));
  auto* Pkg=CreatePackage(*Package); auto* Type=NewObject<UFoliageType_InstancedStaticMesh>(Pkg,FName(*Object),RF_Public|RF_Standalone|RF_Transactional);
  if(!IsValid(Type)) throw std::runtime_error("Native foliage type creation failed"); Type->SetStaticMesh(Mesh);
  if(Type->GetStaticMesh()!=Mesh) throw std::runtime_error("Native foliage type mesh readback mismatch; inspect undo transaction");
  FAssetRegistryModule::AssetCreated(Type); Pkg->MarkPackageDirty();
 }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("type_path"),R.TypePath); J->WriteValue(TEXT("class_path"),UFoliageType_InstancedStaticMesh::StaticClass()->GetPathName()); J->WriteValue(TEXT("mesh_path"),GetPathNameSafe(Mesh)); J->WriteValue(TEXT("created"),!R.bDryRun); J->WriteValue(TEXT("dry_run"),R.bDryRun);
 J->WriteValue(TEXT("scope"),TEXT("New static-mesh foliage type asset at a canonical /Game path with native defaults and optional mesh. Transaction/dry-run, no registration with any foliage actor, no save.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString FoliageUtils::CreateSpawner(const FFoliageReq& R)
{
 FoliageEditorWorld(); if(!GEditor->Trans || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor required");
 FString Package,Object; NewFoliageAssetPath(R.AssetPath,Package,Object);
 if(!R.bDryRun)
 {
  FScopedTransaction Transaction(FText::FromString(TEXT("MCP Create Procedural Foliage Spawner")));
  auto* Pkg=CreatePackage(*Package); auto* Spawner=NewObject<UProceduralFoliageSpawner>(Pkg,FName(*Object),RF_Public|RF_Standalone|RF_Transactional);
  if(!IsValid(Spawner)) throw std::runtime_error("Native procedural foliage spawner creation failed");
  FAssetRegistryModule::AssetCreated(Spawner); Pkg->MarkPackageDirty();
 }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("asset_path"),R.AssetPath); J->WriteValue(TEXT("class_path"),UProceduralFoliageSpawner::StaticClass()->GetPathName()); J->WriteValue(TEXT("created"),!R.bDryRun); J->WriteValue(TEXT("dry_run"),R.bDryRun);
 J->WriteValue(TEXT("scope"),TEXT("New empty procedural foliage spawner asset at a canonical /Game path with native defaults. Transaction/dry-run, no simulation, no save.")); J->WriteObjectEnd(); J->Close(); return Result;
}
